$ErrorActionPreference="Stop"
$D="$env:ProgramData\OfficeDeploy";$R="https://raw.githubusercontent.com/alamaxjashek/OfficeDeploy/main";New-Item $D -ItemType Directory -Force|Out-Null
$Log="$D\uninstall.log";Start-Transcript -Path $Log -Append -Force|Out-Null;$ExitCode=0;$NeedReboot=$false
try{Write-Host "=== VERIFICANDO REINICIO PENDIENTE ===";$RP=(Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending") -or (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired") -or ($null -ne (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager" -Name PendingFileRenameOperations -ErrorAction SilentlyContinue));if($RP){Write-Host "REINICIO PENDIENTE DETECTADO. Reinicie Windows y ejecute nuevamente el desinstalador." -ForegroundColor Yellow;$ExitCode=3010}else{Write-Host "No hay reinicio pendiente." -ForegroundColor Green
Write-Host "=== ETAPA 1: CERRANDO APLICACIONES OFFICE ===";Get-Process WINWORD,EXCEL,OUTLOOK,POWERPNT,MSACCESS,MSPUB,ONENOTE,VISIO,WINPROJ -ErrorAction SilentlyContinue|Stop-Process -Force -ErrorAction SilentlyContinue
Write-Host "=== ETAPA 2: CLICK-TO-RUN / ODT ===";Invoke-WebRequest "$R/setup.exe" -OutFile "$D\setup.exe";Invoke-WebRequest "$R/uninstall.xml" -OutFile "$D\uninstall.xml";$O=Start-Process "$D\setup.exe" -ArgumentList "/configure `"$D\uninstall.xml`"" -Wait -PassThru -NoNewWindow;Write-Host "ODT ExitCode: $($O.ExitCode)";if($O.ExitCode -eq 3010){$NeedReboot=$true}
Write-Host "=== ETAPA 3: OFFICE MSI 2007-2016 ===";$Roots=@("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*","HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*");$Pattern="(?i)(Office|Visio|Project|Access|Excel|Word|PowerPoint|Outlook|Publisher|OneNote).*(2007|2010|2013|2016)";$Items=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.Publisher -like "Microsoft*" -and $_.DisplayName -match $Pattern -and $_.PSChildName -match "^\{[0-9A-Fa-f-]+\}$"});foreach($I in ($Items|Sort-Object PSChildName -Unique)){Write-Host "Desinstalando: $($I.DisplayName) [$($I.PSChildName)]";$M=Start-Process msiexec.exe -ArgumentList "/x `"$($I.PSChildName)`" /qn /norestart /L*v `"$D\MSI-$($I.PSChildName.Trim('{' ,'}' )).log`"" -Wait -PassThru;Write-Host "MSI ExitCode: $($M.ExitCode)";if($M.ExitCode -eq 3010){$NeedReboot=$true}elseif($M.ExitCode -notin @(0,1605)){Write-Warning "Fallo MSI $($I.DisplayName): ExitCode $($M.ExitCode)";$ExitCode=1}}
Write-Host "=== VERIFICACION FINAL ===";$Left=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match "(?i)Office Professional Plus (2007|2010|2013|2016)|Office Professional (2007|2010|2013|2016)"});$Exe=@("C:\Program Files\Microsoft Office\Office16\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office16\WINWORD.EXE")|Where-Object{Test-Path $_};if($Left.Count -gt 0 -or $Exe.Count -gt 0){Write-Host "QUEDAN COMPONENTES OFFICE:" -ForegroundColor Red;$Left|Select DisplayName,DisplayVersion,PSChildName|Format-Table -AutoSize;$Exe|ForEach-Object{Write-Host "EXISTE: $_" -ForegroundColor Red};if($ExitCode -eq 0){$ExitCode=1}}elseif($NeedReboot -and $ExitCode -eq 0){Write-Host "Office eliminado. REINICIO REQUERIDO." -ForegroundColor Yellow;$ExitCode=3010}else{Write-Host "Office antiguo eliminado correctamente." -ForegroundColor Green}}}catch{Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red;$ExitCode=1}finally{Stop-Transcript -ErrorAction SilentlyContinue};exit $ExitCode